import {useEffect,useState} from 'react'; import {onAuthStateChanged,signInWithEmailAndPassword,signOut,createUserWithEmailAndPassword,updateProfile,sendEmailVerification,sendPasswordResetEmail,reload,getIdToken} from 'firebase/auth'; import {addDoc,collection,doc,onSnapshot,serverTimestamp,query,orderBy,limit,getDoc,updateDoc,deleteDoc,runTransaction,writeBatch} from 'firebase/firestore'; import {Activity,ArrowDownRight,ArrowUpRight,BarChart3, Bell, ChevronDown, CircleDollarSign, Download, LayoutDashboard, LogOut, Menu, Plus, Search, ShieldCheck, Ticket, Users, Wallet, X} from 'lucide-react'; import {Doughnut,Bar} from 'react-chartjs-2'; import {Chart as ChartJS,ArcElement,Tooltip,Legend,CategoryScale,LinearScale,BarElement} from 'chart.js'; import {auth,db,configured} from './firebase'; import {formatNaira,parseNaira} from './money'; import BudgetEditor from './components/BudgetEditor'; import TicketTierEditor from './components/TicketTierEditor'; import type {Allocation,Expense,Person,Revenue,Role,Tier} from './types';
ChartJS.register(ArcElement,Tooltip,Legend,CategoryScale,LinearScale,BarElement);
const seedTiers:Tier[]=[{id:'early-bird',name:'Early Bird',price:5000,capacity:150,sold:0,active:true},{id:'regular',name:'Regular',price:8000,capacity:540,sold:0,active:true},{id:'vip-experience',name:'VIP Experience',price:150000,capacity:10,sold:0,active:true}];
