const nav:{name:Page;icon:any;group:string}[]=[{name:'Overview',icon:LayoutDashboard,group:'WORKSPACE'},{name:'Tickets',icon:Ticket,group:'WORKSPACE'},{name:'Revenues',icon:ArrowUpRight,group:'WORKSPACE'},{name:'Expenses',icon:ArrowDownRight,group:'WORKSPACE'},{name:'Budget',icon:Wallet,group:'WORKSPACE'},{name:'Categories',icon:BarChart3,group:'MANAGE'},{name:'Reports',icon:Download,group:'MANAGE'},{name:'User management',icon:Users,group:'MANAGE'},{name:'Activity log',icon:Activity,group:'MANAGE'}];
